Given two strings s1 and s2 consisting of lowercase English letters of length n1 and n2 respectively, find the number of ways to insert exactly one character into string s1 such that the length of the Longest Common Subsequence (LCS) of both strings increases by exactly 1.Examples:  Input: s1 = "abab", s2 = "abc"Output: 3Explanation: The LCS length of the given two strings is 2. There are 3 valid insertions in s1 which increase the LCS length to 3:"abcab" -> LCS = 3"abacb" -> LCS = 3"ababc" -> LCS = 3Input: s1 = "abcabc", s2 = "abcd"Output: 4Explanation: The LCS length of the given two strings is 3. There are 4 valid insertions in s1 which increase the LCS length to 4:"abcdabc" -> LCS = 4"abcadcb" -> LCS = 4"abcabdc" -> LCS = 4"abcabcd" -> LCS = 4Try It YourselfTable of Content[Naive Approach] Brute Force - O(n1 × 26 × (n1 × n2)) Time and O(n1 × n2) Space[Expected Approach] Prefix and Suffix DP - O(n1 × n2) Time and O(n1 × n2) Space[Naive Approach] Brute Force - O(n1 × 26 × (n1 × n2)) Time and O(n1 × n2) SpaceThe idea is to simulate the insertion of every possible lowercase character (a to z) at every possible position in s1 and compute the LCS of the modified s1 with s2. If the LCS length increases by one after the insertion, we count it as a valid way. This approach checks all possible combinations of insertions and directly verifies whether the LCS length increases.Note : The DP solution of the LCS problem has been directly used in the code below.
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Returns length of LCS for s1[0..m-1], s2[0..n-1]
int lcs(string &s1, string &s2) {
    int n1 = s1.size();
    int n2 = s2.size();

    vector<vector<int>> dp(n1 + 1, vector<int>(n2 + 1, 0));

    // Building dp in bottom-up fashion
    for (int i = 1; i <= n1; ++i) {
        for (int j = 1; j <= n2; ++j) {
            if (s1[i - 1] == s2[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    return dp[n1][n2];
}

// Method returns total ways to increase LCS length by 1
int waysToIncreaseLCSBy1(string &s1, string &s2) {
    int n1 = s1.length();
    int n2 = s2.length();

    // Find original LCS
    int lcs1 = lcs(s1, s2);

    int ways = 0;

    // Try all insertion positions in s1
    for (int i = 0; i <= n1; i++) {

        // Try all characters from 'a' to 'z'
        for (char ch = 'a'; ch <= 'z'; ch++) {

            // Form new string after insertion
            string updatedStr = s1.substr(0, i) + ch + s1.substr(i);

            // Compute LCS with updated string
            int lcs2 = lcs(updatedStr, s2);

            // Check if LCS increases by exactly 1
            if (lcs2 == lcs1 + 1)
                ways++;
        }
    }

    return ways;
}

int main() {
    string s1 = "abab";
    string s2 = "abc";

    cout << waysToIncreaseLCSBy1(s1, s2);
    return 0;
}


